using HotChocolate.Authorization;
using GraphApi.Infrastructure.Services;using GraphApi.Models.ANM.TiposAnuncio;using GraphApi.Services.ANM.TiposAnuncio;using HotChocolate;using System.Linq;namespace GraphApi.GraphQL.ANM.TiposAnuncio{    [MutationType]    [GraphQLDescription("Punto de entrada para las mutaciones de TiposAnuncios: creación, actualización y eliminación.")]    public class TiposAnuncioMutation    {        [Authorize]        [GraphQLName("createTiposAnuncio")]        [GraphQLDescription("Crea un nuevo TiposAnuncio usando los headers 'UserID' y 'WindowName'.")]        public async Task<clReadTiposAnuncio> CreateTiposAnuncioAsync(            [GraphQLDescription("Datos necesarios para crear el TiposAnuncio.")]            clCreateTiposAnuncio objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de TiposAnuncio.")]            ITiposAnuncioService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.CreateTiposAnuncio(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("updateTiposAnuncio")]        [GraphQLDescription("Actualiza los campos especificados de un TiposAnuncio existente.")]        public async Task<clReadTiposAnuncio?> UpdateTiposAnuncioAsync(            [GraphQLDescription("Datos del TiposAnuncio a actualizar.")]            clUpdateTiposAnuncio objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de TiposAnuncio.")]            ITiposAnuncioService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.UpdateTiposAnuncio(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("deleteTiposAnuncio")]        [GraphQLDescription("Elimina un TiposAnuncio por su ID.")]        public async Task<bool> delTiposAnuncioAsync(            [GraphQLDescription("ID del TiposAnuncio a eliminar.")]            int nTiposAnuncioID,            [Service]            [GraphQLDescription("Servicio para operaciones de TiposAnuncio.")]            ITiposAnuncioService objService        )        {            return await objService.DeleteTiposAnuncio(nTiposAnuncioID);        }    }}